 "content": "def transform(grid):
    """Replace each isolated marker with the horizontal pattern shown in the grid."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(x for row in g for x in row).most_common(1)[0][0]

    # The exemplar is the longest contiguous horizontal non-background run.
    runs = []
    for r, row in enumerate(g):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if c - start > 1:
                runs.append((c - start, r, start, row[start:c]))
    if not runs:
        return g
    _, pr, ps, pattern = max(runs)
    plen = len(pattern)
    exemplar_cells = {(pr, c) for c in range(ps, ps + plen)}

    # Every other non-background cell is a marker; place the exemplar with
    # its midpoint aligned to that marker, leaving the exemplar itself intact.
    markers = [(r, c) for r in range(h) for c in range(w)
               if g[r][c] != bg and (r, c) not in exemplar_cells]
    for r, c in markers:
        left = c - plen // 2
        for i, color in enumerate(pattern):
            cc = left + i
            if 0 <= cc < w:
                g[r][cc] = color
    return g
